"""Render the reviewed statement inventory without inventing proof status."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LABELS = {
    'complete': '完整证明（所列依赖下）',
    'external': '引用定理',
    'outline': '证明概要 / Advanced Outline',
    'pending': '待审',
}


def render(data):
    statements = data['statements']
    by_id = {s['id']: s for s in statements}
    parts = [
        '# 逐定理证明与依赖台账',
        '<!-- Generated by scripts/build_proof_ledger.py; edit scripts/proof-ledger.json. -->',
        f"本表覆盖 {'、'.join(data['scope'])} 的主要编号结论与显式引用，共{len(statements)}项、{len(data['scope'])}章。"
        '没有把它称作全书定理审计。其他章节仍以[逐章记录](reviews/index.md)为准，未进入此表不等于已验证。',
        '“完整证明”描述本地论证的展开范围，**允许依赖已精确声明的外引**；它不表示形式化认证或人类签署。'
        '“引用定理”把完整证明责任交给文献；“证明概要”保留尚未展开的步骤；“待审”标记尚不能认可的陈述。'
        '每项列假设、依赖与人工复核义务，构建测试只检查台账和页面一致。',
        '本批补 H2 的细分、小链、切除与 Mayer–Vietoris 完整推导，继而在 H3.4/H3.1/H3.5/H3.6 '
        '建立有限（可非正则）CW 骨架相对群、胞腔比较、附加度公式及任意阿贝尔系数版本。'
        'Q1 胞腔上链比较、Q2.2 对偶比较、H3.EZ 空间乘积比较仍外引或概要，G1.2 核像识别仍待展开。'
        '没有用有限测试替代一般定理的证明。',
        '参考链接定位到真实书籍/论文入口；本批访问 Hatcher 作者入口，未逐页读取原书，不虚报核查范围。'
        'H2/H3 本批及 H3/Q1/Q2 前批由作者、根代理与非编写模型逐式复核；具体范围见逐章记录。'
        '全部内容仍需独立人类复核，不是形式化认证。',
    ]
    for s in statements:
        ref = data['references'][s['reference']]
        deps = '、'.join(f"[{d}](#{by_id[d]['anchor']})" for d in s['dependencies']) or '本章定义与所列基础工具'
        parts.extend([
            f"## {s['id']} {{#{s['anchor']}}}",
            f"[{s['chapter']} 正文位置](../{s['path']}#{s['anchor']}) · **{LABELS[s['kind']]}**",
            f"- 假设与基础：{s['assumptions']}。\n"
            f"- 依赖：{deps}。\n"
            f"- 审查范围/未尽义务：{s['obligation']}。\n"
            f"- 参考定位：[{ref['title']}]({ref['url']})。\n"
            f"- 审查状态：{s['review']}。",
        ])
    return '\n\n'.join(parts) + '\n'


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    data = json.loads((ROOT / 'scripts/proof-ledger.json').read_text(encoding='utf-8'))
    target = ROOT / 'docs/project/proof-ledger.md'
    expected = render(data)
    if args.check:
        assert target.read_text(encoding='utf-8') == expected, 'Proof ledger stale: run python scripts/build_proof_ledger.py'
    else:
        target.write_text(expected, encoding='utf-8')
    print(f"PASS ledger: {len(data['statements'])} statements in {len(data['scope'])} chapters; status is recorded, not certified")


if __name__ == '__main__':
    main()
